import { existsSync, readFileSync, readdirSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { pnpm } from '../process.ts';
import { applyFiles, digest, recover, walk, type Files } from './files.ts';
import { flags, projectOptions, selectedPackages, validateName } from './options.ts';
import { appFiles, projectFiles, infrastructureFiles, type TemplateState } from './render.ts';
import { safeFile } from './safety.ts';
import { formatterKey } from './format.ts';

export const templateRoot = path.resolve(fileURLToPath(new URL('../..', import.meta.url)));
export function readState(root: string): TemplateState | undefined {
  if (!existsSync(root)) return undefined;
  const filename = safeFile(root, '.template.json');
  return existsSync(filename)
    ? (JSON.parse(readFileSync(filename, 'utf8')) as TemplateState)
    : undefined;
}

export function reconcile(
  root: string,
  files: Files,
  previous?: TemplateState,
): { writes: Files; remove: string[] } {
  const writes: Files = new Map();
  const remove: string[] = [];
  for (const [relative, contents] of files) {
    const target = safeFile(root, relative);
    if (existsSync(target)) {
      const current = digest(readFileSync(target));
      if (current === digest(contents)) continue;
      if (relative !== '.template.json' && current !== previous?.managed[relative])
        throw new Error(`User change or collision: ${relative}; review the diff before migration`);
    }
    writes.set(relative, contents);
  }
  for (const relative of Object.keys(previous?.managed ?? {})) {
    if (files.has(relative)) continue;
    const target = safeFile(root, relative);
    if (!existsSync(target)) continue;
    if (digest(readFileSync(target)) !== previous?.managed[relative])
      throw new Error(`Refusing to delete user change: ${relative}`);
    remove.push(relative);
  }
  return { writes, remove };
}

export async function main(args: string[]): Promise<void> {
  const command = args[0];
  if (!['init', 'sync', 'add'].includes(command ?? ''))
    throw new Error('Usage: node tools/generators/cli.ts init|sync|add [flags]; see README');
  const input = flags(args.slice(1));
  const allowed = [
    'name',
    'scope',
    'identifier',
    'preset',
    'features',
    'target',
    'dry-run',
    'reference',
    'check',
    'no-install',
    'recover',
    'kind',
  ];
  for (const key of Object.keys(input))
    if (!allowed.includes(key)) throw new Error(`Unknown flag: --${key}`);
  const root = path.resolve(typeof input.target === 'string' ? input.target : process.cwd());
  if (input.recover && input['dry-run'])
    throw new Error('--recover changes files and cannot be combined with --dry-run');
  if (input.recover) recover(root);
  const previous = readState(root);
  let files: Files;
  let remove: string[] = [];
  if (command === 'sync') {
    if (previous?.kind !== 'reference')
      throw new Error(
        'sync is only for the reference workspace; generated projects use reviewed version migrations',
      );
    files = new Map(
      selectedPackages(previous.options).flatMap((kind) => [
        ...appFiles(templateRoot, previous.options, kind),
      ]),
    );
    const packages = new Set(selectedPackages(previous.options));
    for (const [name, options] of Object.entries(previous.referenceApps ?? {})) {
      validateName(name);
      if (selectedPackages(previous.options).includes(name))
        throw new Error(`Reference app name conflicts with preset: ${name}`);
      const validated = projectOptions({ ...options, features: options.features.join(',') });
      if (!['api', 'web', 'desktop'].includes(validated.preset))
        throw new Error(`Reference app must use an application preset: ${name}`);
      for (const [filename, contents] of appFiles(templateRoot, validated, validated.preset, name))
        files.set(filename, contents);
      packages.add(name);
      for (const shared of selectedPackages(validated).filter(
        (kind) => !['api', 'web', 'desktop'].includes(kind),
      )) {
        if (packages.has(shared)) continue;
        for (const [filename, contents] of appFiles(templateRoot, validated, shared))
          files.set(filename, contents);
        packages.add(shared);
      }
    }
    const roots = [...packages].map((name) => `packages/${name}/`);
    const owned = Object.fromEntries(
      Object.entries(previous.managed).filter(([filename]) =>
        roots.some((prefix) => filename.startsWith(prefix)),
      ),
    );
    // Infrastructure in a reference workspace is authored here. Record its current
    // baseline for future template clones without modifying any of those files.
    const retained = Object.fromEntries(
      [...infrastructureFiles(root)].map(([filename, contents]) => [filename, digest(contents)]),
    );
    const state = {
      ...previous,
      packages: [...packages],
      managed: {
        ...retained,
        ...Object.fromEntries(
          [...files].map(([filename, contents]) => [filename, digest(contents)]),
        ),
      },
    };
    const lock = path.join(root, 'pnpm-lock.yaml');
    if (existsSync(lock)) state.lockId = digest(readFileSync(lock));
    // A normal sync prepares dependencies after rendering; setup records its final lock.
    if (!input['no-install'] && !input.check && !input['dry-run']) state.lockPending = true;
    const key = formatterKey(root);
    if (key) state.formatKey = key;
    files.set('.template.json', Buffer.from(`${JSON.stringify(state, null, 2)}\n`));
    const planned = reconcile(root, files, { ...previous, managed: owned });
    if (input.check) {
      if (planned.writes.size || planned.remove.length)
        throw new Error(
          `Reference drift: ${[...planned.writes.keys(), ...planned.remove].join(', ')}; edit blueprints and run template:sync`,
        );
      console.log('Reference matches canonical blueprints');
      return;
    }
    files = planned.writes;
    remove = planned.remove;
  } else if (command === 'add') {
    if (!previous) throw new Error('Initialize the project before adding an app');
    if (
      typeof input.kind !== 'string' ||
      !['web', 'api', 'desktop'].includes(input.kind) ||
      typeof input.name !== 'string'
    )
      throw new Error('add requires --kind web|api|desktop --name <directory>');
    validateName(input.name);
    const appDirectory = safeFile(root, `packages/${input.name}`);
    if (existsSync(safeFile(root, `packages/${input.name}/package.json`)))
      throw new Error(`App already exists: ${input.name}`);
    const appOutputs = new Set([
      'node_modules',
      'dist',
      '.cloudflare',
      '.wrangler',
      'artifacts',
      'test-results',
      'playwright-report',
      'src/routeTree.gen.ts',
      ...(input.kind === 'desktop'
        ? [
            'src-tauri/target',
            'src-tauri/icons',
            'src-tauri/gen',
            'src-tauri/permissions/autogenerated',
          ]
        : []),
    ]);
    if (existsSync(appDirectory) && walk(appDirectory, '', new Set(), appOutputs).length)
      throw new Error(`App directory contains user files: ${input.name}`);
    const options = projectOptions({
      name: previous.options.name,
      scope: previous.options.scope,
      identifier:
        input.identifier ?? `${previous.options.identifier}.${input.name.replaceAll('-', '')}`,
      preset: input.kind,
      features: input.features ?? '',
    });
    if (`${options.name}-${input.name}`.length > 63)
      throw new Error('Combined Worker name must be at most 63 characters');
    if (input.kind === 'desktop') {
      const { workspacePackages } = await import('../quality/graph.ts');
      for (const existing of workspacePackages(root).filter((pkg) => pkg.runtime === 'desktop')) {
        const config = JSON.parse(
          readFileSync(safeFile(root, `${existing.directory}/src-tauri/tauri.conf.json`), 'utf8'),
        ) as { identifier: string };
        if (config.identifier === options.identifier)
          throw new Error(
            `Desktop identifier collision: ${options.identifier}; choose --identifier`,
          );
      }
    }
    files = appFiles(root, options, input.kind, input.name);
    for (const shared of selectedPackages(options).filter(
      (value) => !['web', 'api', 'desktop'].includes(value),
    )) {
      const sharedManifest = safeFile(root, `packages/${shared}/package.json`);
      if (existsSync(sharedManifest)) {
        const manifest = JSON.parse(readFileSync(sharedManifest, 'utf8')) as { name?: string };
        if (manifest.name !== `${options.scope}/${shared}`)
          throw new Error(`Shared package identity collision: ${shared}`);
      } else {
        const directory = safeFile(root, `packages/${shared}`);
        if (
          existsSync(directory) &&
          walk(directory, '', new Set(['node_modules', 'dist', 'artifacts'])).length
        )
          throw new Error(`Shared package directory contains user files: ${shared}`);
        for (const [filename, contents] of appFiles(root, options, shared))
          files.set(filename, contents);
      }
    }
    const manifest = JSON.parse(readFileSync(path.join(root, 'package.json'), 'utf8')) as {
      scripts: Record<string, string>;
    };
    if (manifest.scripts[`dev:${input.name}`])
      throw new Error(`Existing user script dev:${input.name} is protected`);
    manifest.scripts[`dev:${input.name}`] = `node tools/dev-environment/dev.ts ${input.name}`;
    files.set('package.json', Buffer.from(`${JSON.stringify(manifest, null, 2)}\n`));
    const state = {
      ...previous,
      ...(previous.kind === 'reference'
        ? { referenceApps: { ...previous.referenceApps, [input.name]: options } }
        : {}),
      lockPending: true,
      packages: [
        ...new Set([
          ...previous.packages,
          input.name,
          ...selectedPackages(options).filter(
            (value) => !['web', 'api', 'desktop'].includes(value),
          ),
        ]),
      ],
      managed: {
        ...previous.managed,
        ...Object.fromEntries(
          [...files].map(([filename, contents]) => [filename, digest(contents)]),
        ),
      },
    };
    // A cold add cannot format its new files. The inherited key only covers the
    // previous managed inputs; setup must finalize unchanged new scaffold files.
    if (!formatterKey(root)) delete state.formatKey;
    files.set('.template.json', Buffer.from(`${JSON.stringify(state, null, 2)}\n`));
    for (const filename of files.keys())
      if (
        filename !== 'package.json' &&
        filename !== '.template.json' &&
        existsSync(safeFile(root, filename))
      )
        throw new Error(`Collision: ${filename}`);
  } else {
    const options = projectOptions(input);
    if (
      previous?.kind === 'project' &&
      JSON.stringify(previous.options) === JSON.stringify(options)
    ) {
      console.log(
        'Already initialized; user changes preserved. Run env:setup for pending installation.',
      );
      return;
    }
    if (!previous && existsSync(root) && readdirSync(root).some((entry) => entry !== '.git'))
      throw new Error(
        'Initialization requires an empty directory or a template reference clone; existing files are protected',
      );
    files = projectFiles(templateRoot, options, input.reference ? 'reference' : 'project');
    if (previous) ({ writes: files, remove } = reconcile(root, files, previous));
  }
  console.log(
    JSON.stringify(
      { root, writes: files.size, remove, dryRun: Boolean(input['dry-run']) },
      null,
      2,
    ),
  );
  if (input['dry-run']) return;
  applyFiles(root, files, remove);
  if (!input['no-install']) {
    await pnpm(['install', '--no-frozen-lockfile'], { cwd: root });
    await pnpm(['env:setup'], { cwd: root });
  }
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  await main(process.argv.slice(2)).catch((error: unknown) => {
    console.error(error instanceof Error ? error.message : error);
    process.exitCode = 1;
  });
}

import { spawnSync } from 'node:child_process';
import {
  existsSync,
  mkdirSync,
  mkdtempSync,
  readFileSync,
  rmSync,
  symlinkSync,
  writeFileSync,
} from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { expect, it } from 'vitest';
import { finalizeManaged, formatFiles } from './format.ts';
import { main, readState } from './cli.ts';
import { applyFiles } from './files.ts';
import { projectOptions } from './options.ts';
import { projectFiles } from './render.ts';
import { spawnOwned, stopTree } from '../process.ts';

const source = path.resolve(import.meta.dirname, '../..');
function fixture(config: string, run: (root: string) => void): void {
  const root = mkdtempSync(path.join(os.tmpdir(), 'starter-format-'));
  try {
    symlinkSync(path.join(source, 'node_modules'), path.join(root, 'node_modules'), 'junction');
    writeFileSync(path.join(root, 'package.json'), '{"type":"module"}');
    writeFileSync(path.join(root, 'vite.config.ts'), config);
    run(root);
  } finally {
    // Use Node's bounded filesystem retries for Windows removal refusals.
    // Persistent failures still throw; this does not infer a child-process leak.
    rmSync(root, { recursive: true, force: true, maxRetries: 3, retryDelay: 100 });
    expect(existsSync(root)).toBe(false);
  }
}
const simple =
  'export default { fmt: { singleQuote: true, ignorePatterns: ["packages/cache/dist/**"] } };';
function cli(root: string, filename: string, contents: Buffer): Buffer {
  const result = spawnSync(
    process.execPath,
    [path.join(root, 'node_modules/vite-plus/bin/vp'), 'fmt', '--stdin-filepath', filename],
    { cwd: root, input: contents, timeout: 30_000 },
  );
  expect({ status: result.status, stderr: result.stderr.toString() }).toEqual({
    status: 0,
    stderr: '',
  });
  return result.stdout;
}

it.each(['absent', 'partial'])(
  'finalizes a cold add with %s SDK and preserves user edits',
  async (sdk) => {
    const root = mkdtempSync(path.join(os.tmpdir(), 'starter-cold-add-'));
    try {
      const options = projectOptions({
        name: 'formatter-cold-add',
        scope: '@formatter-add',
        preset: 'api',
      });
      applyFiles(root, projectFiles(source, options));
      expect(readState(root)?.formatKey).toBeDefined();
      expect(existsSync(path.join(root, 'node_modules'))).toBe(false);
      if (sdk === 'partial') {
        const directory = path.join(root, 'node_modules/vite-plus');
        mkdirSync(directory, { recursive: true });
        writeFileSync(
          path.join(directory, 'package.json'),
          readFileSync(path.join(source, 'node_modules/vite-plus/package.json')),
        );
      }
      await main(['add', '--kind', 'api', '--name', 'status', '--target', root, '--no-install']);
      expect(readState(root)?.formatKey).toBeUndefined();

      const filename = 'packages/status/cloudflare.config.ts';
      const unformatted = readFileSync(path.join(root, filename));
      const userFile = path.join(root, 'packages/status/src/notes.ts');
      const userBytes = Buffer.concat([readFileSync(userFile), Buffer.from('\n// user change\n')]);
      writeFileSync(userFile, userBytes);
      rmSync(path.join(root, 'node_modules'), { recursive: true, force: true });
      symlinkSync(path.join(source, 'node_modules'), path.join(root, 'node_modules'), 'junction');
      const expected = cli(root, filename, unformatted);
      expect(unformatted).not.toEqual(expected);
      finalizeManaged(root);
      expect(readFileSync(path.join(root, filename))).toEqual(expected);
      expect(readFileSync(userFile)).toEqual(userBytes);
      const finalized = readFileSync(path.join(root, '.template.json'));
      finalizeManaged(root);
      expect(readFileSync(path.join(root, '.template.json'))).toEqual(finalized);
    } finally {
      rmSync(root, { recursive: true, force: true, maxRetries: 3, retryDelay: 100 });
      expect(existsSync(root)).toBe(false);
    }
  },
);

it('matches the owning SDK CLI for mixed scripts, ignored build output and JSON', () => {
  fixture(simple, (root) => {
    const files = new Map([
      ['packages/cache/src/example.ts', Buffer.from('export const value="quoted";')],
      ['packages/cache/src/view.tsx', Buffer.from('export const view=<button>go</button>;')],
      ['packages/cache/dist/ignored.ts', Buffer.from('export const untouched= [1,2];')],
      ['package.json', Buffer.from('{"name":"parity","type":"module"}')],
    ]);
    const expected = new Map(
      [...files].map(([name, contents]) => [name, cli(root, name, contents)]),
    );
    expect(formatFiles(root, files)).toEqual(expected);
    expect(files.get('packages/cache/src/example.ts')?.toString()).toContain("'quoted'");
    expect(files.get('packages/cache/dist/ignored.ts')?.toString()).toBe(
      'export const untouched= [1,2];',
    );
  });
});

it.each([
  [
    'custom formatter option',
    'export default { fmt: { singleQuote: false, semi: false, ignorePatterns: [] } };',
    false,
  ],
  ['editorconfig', simple, true],
])('retains CLI semantics with %s', (_, config, editorconfig) => {
  fixture(config, (root) => {
    if (editorconfig)
      writeFileSync(
        path.join(root, '.editorconfig'),
        'root = true\n[*]\nindent_style = space\nindent_size = 4\n',
      );
    const filename = `fallback-${editorconfig ? 'editor' : 'options'}.ts`;
    const contents = Buffer.from('export function fallback(){return "value";}');
    const expected = cli(root, filename, contents);
    expect(formatFiles(root, new Map([[filename, contents]])).get(filename)).toEqual(expected);
    expect(expected.toString().includes(';')).toBe(editorconfig);
    expect(readFileSync(path.join(root, 'vite.config.ts'), 'utf8')).toBe(config);
  });
});

it('rejects a malformed script before installing any batch output', () => {
  fixture(simple, (root) => {
    const files = new Map([
      ['atomic-valid.ts', Buffer.from('export const atomicValid="value";')],
      ['atomic-invalid.ts', Buffer.from('export const = ;')],
    ]);
    const original = new Map(files);
    expect(() => formatFiles(root, files)).toThrow('Generated batch format failed');
    expect(files).toEqual(original);
  });
});

it('invalidates cached formatting across roots and after a side configuration change', () => {
  fixture(simple, (first) => {
    const filename = 'cache-protection.ts';
    const contents = Buffer.from('export function cacheProtection(){return "value";}');
    const format = (root: string) =>
      formatFiles(root, new Map([[filename, contents]])).get(filename)!;
    const before = format(first);
    expect(before.toString()).toContain("\n  return 'value';");
    const editorconfig = 'root = true\n[*]\nindent_style = space\nindent_size = 4\n';
    fixture(simple, (second) => {
      writeFileSync(path.join(second, '.editorconfig'), editorconfig);
      expect(format(second)).toEqual(cli(second, filename, contents));
      expect(format(second).toString()).toContain("\n    return 'value';");
    });
    writeFileSync(path.join(first, '.editorconfig'), editorconfig);
    expect(format(first)).toEqual(cli(first, filename, contents));
    expect(format(first)).not.toEqual(before);
  });
});

it('matches CLI stdin behavior for a gitignored source file and CLI runtime metadata', () => {
  fixture(
    'export default {fmt:{singleQuote:process.env.JS_RUNTIME_VERSION === process.versions.node && process.env.JS_RUNTIME_NAME === process.release.name && process.env.NODE_PACKAGE_MANAGER === "vite-plus",ignorePatterns:[]}};',
    (root) => {
      writeFileSync(path.join(root, '.gitignore'), 'gitignored.ts\n');
      const contents = Buffer.from('export const metadata="value";');
      const output = formatFiles(root, new Map([['gitignored.ts', contents]])).get('gitignored.ts');
      expect(output).toEqual(cli(root, 'gitignored.ts', contents));
      expect(output?.toString()).toContain("'value'");
    },
  );
});

it('reports malformed formatting before naturally draining a tracked SDK child', async () => {
  const root = mkdtempSync(path.join(os.tmpdir(), 'starter-format-drain-'));
  const snapshot = path.join(root, 'exit-snapshot.json');
  const server = path.join(root, 'sdk-child.mjs');
  symlinkSync(path.join(source, 'node_modules'), path.join(root, 'node_modules'), 'junction');
  writeFileSync(path.join(root, 'package.json'), '{"type":"module"}');
  writeFileSync(
    server,
    "import {createServer} from 'node:http';const server=createServer((request,response)=>{if(request.url!=='/release'){response.statusCode=404;response.end();return;}response.end('released');server.close();});server.listen(0,'127.0.0.1',()=>console.log('FORMAT_CHILD '+JSON.stringify({origin:'http://127.0.0.1:'+server.address().port,pid:process.pid})));",
  );
  writeFileSync(
    path.join(root, 'vite.config.ts'),
    `import {spawn} from 'node:child_process';import {writeFileSync} from 'node:fs';const child=spawn(process.execPath,[process.env.FORMAT_DRAIN_CHILD],{stdio:['ignore','inherit','inherit']});process.on('exit',()=>writeFileSync(process.env.FORMAT_DRAIN_SNAPSHOT,JSON.stringify({code:child.exitCode,signal:child.signalCode})));${simple}`,
  );
  const child = spawnOwned(
    process.execPath,
    [
      '--input-type=module',
      '--eval',
      readFileSync(new URL('./format-batch.mjs', import.meta.url), 'utf8'),
    ],
    {
      cwd: root,
      stdio: ['pipe', 'pipe', 'pipe'],
      env: { ...process.env, FORMAT_DRAIN_CHILD: server, FORMAT_DRAIN_SNAPSHOT: snapshot },
    },
  );
  const closed = new Promise<void>((resolve) => child.once('close', () => resolve()));
  let output = '';
  let error = '';
  let timer: ReturnType<typeof setTimeout> | undefined;
  try {
    const ready = new Promise<string>((resolve, reject) => {
      const check = () => {
        if (!error.includes('Generated format failed for atomic-invalid.ts')) return;
        // A fatal unhandled exception emits host exit before its error diagnostic.
        // Managed teardown cannot change the snapshot of the child at that moment.
        if (existsSync(snapshot)) {
          reject(
            new Error(
              `Formatter exited before draining its SDK child: ${readFileSync(snapshot, 'utf8')}`,
            ),
          );
          return;
        }
        const origin = /FORMAT_CHILD (\{[^\n]+\})/u.exec(output)?.[1];
        if (origin) resolve((JSON.parse(origin) as { origin: string }).origin);
      };
      child.stdout?.on('data', (chunk: Buffer) => {
        output += chunk.toString();
        check();
      });
      child.stderr?.on('data', (chunk: Buffer) => {
        error += chunk.toString();
        check();
      });
      child.once('error', reject);
      child.once('exit', () => reject(new Error(`Formatter exited before SDK release: ${error}`)));
      timer = setTimeout(() => reject(new Error('Formatter SDK child readiness timeout')), 15_000);
    });
    child.stdin?.end(
      JSON.stringify({ entries: [['atomic-invalid.ts', 'export const = ;']], sideConfigs: [] }),
    );
    const origin = await ready;
    if (timer) clearTimeout(timer);
    expect(existsSync(snapshot)).toBe(false);
    expect(
      await (await fetch(`${origin}/release`, { signal: AbortSignal.timeout(1000) })).text(),
    ).toBe('released');
    await closed;
    await stopTree(child, 0);
    expect(child.exitCode).toBe(1);
    expect(error).toContain('Generated format failed for atomic-invalid.ts');
    expect(output).not.toContain('STARTER_FORMAT_BATCH');
    expect(JSON.parse(readFileSync(snapshot, 'utf8'))).toEqual({ code: 0, signal: null });
  } finally {
    if (timer) clearTimeout(timer);
    await stopTree(child, 0);
    rmSync(root, { recursive: true, force: true, maxRetries: 3, retryDelay: 100 });
    expect(existsSync(root)).toBe(false);
  }
});

import { spawnSync } from 'node:child_process';
import { existsSync, readFileSync } from 'node:fs';
import path from 'node:path';
import type { Files } from './files.ts';
import { digest, applyFiles } from './files.ts';
import type { TemplateState } from './render.ts';
import { safeFile } from './safety.ts';

const formatted = new Map<string, Buffer>();
const sideConfigs = [
  '.editorconfig',
  '.oxfmtrc.json',
  '.oxfmtrc.jsonc',
  '.prettierignore',
  '.prettierrc',
  '.prettierrc.json',
  '.prettierrc.yml',
  '.prettierrc.yaml',
  '.prettierrc.js',
  '.prettierrc.cjs',
  'prettier.config.js',
  'prettier.config.cjs',
];
export function formatterKey(root: string): string | undefined {
  const manifest = path.join(root, 'node_modules/vite-plus/package.json');
  const binary = path.join(root, 'node_modules/vite-plus/bin/vp');
  if (!existsSync(manifest) || !existsSync(binary)) return undefined;
  const version = (JSON.parse(readFileSync(manifest, 'utf8')) as { version: string }).version;
  return digest(`${version}\0${readFileSync(path.join(root, 'vite.config.ts'), 'utf8')}`);
}

// Rendering delegates layout to the pinned, project-local formatter, never a second formatter.
// Cold bootstrap renders without dependencies; setup finalizes only unchanged managed files.
export function formatFiles(root: string, files: Files): Files {
  const binary = path.join(root, 'node_modules/vite-plus/bin/vp');
  if (!existsSync(binary)) return files;
  const formatter = formatterKey(root);
  const directories = new Map<string, string>();
  const sideKey = (directory: string): string => {
    const cached = directories.get(directory);
    if (cached) return cached;
    const parent = path.dirname(directory);
    const key = digest(
      [
        directory === parent ? '' : sideKey(parent),
        ...sideConfigs.map((filename) => {
          const target = path.join(directory, filename);
          return existsSync(target) ? `${target}\0${digest(readFileSync(target))}` : '';
        }),
      ].join('\0'),
    );
    directories.set(directory, key);
    return key;
  };
  const pending: [string, Buffer, string][] = [];
  for (const [filename, contents] of files) {
    if (!/\.(?:[cm]?[jt]sx?|json|css|html|md)$/u.test(filename)) continue;
    const key = digest(
      Buffer.concat([
        Buffer.from(
          `${path.resolve(root)}\0${formatter}\0${sideKey(path.dirname(path.resolve(root, filename)))}\0${filename}\0`,
        ),
        contents,
      ]),
    );
    const cached = formatted.get(key);
    if (cached) {
      files.set(filename, cached);
      continue;
    }
    pending.push([filename, contents, key]);
  }
  const scripts = pending.filter(([filename]) => /\.[cm]?[jt]sx?$/u.test(filename));
  if (scripts.length) {
    const batch = spawnSync(
      process.execPath,
      [
        '--input-type=module',
        '--eval',
        readFileSync(new URL('./format-batch.mjs', import.meta.url), 'utf8'),
      ],
      {
        cwd: root,
        input: JSON.stringify({
          entries: scripts.map(([filename, contents]) => [filename, contents.toString()]),
          sideConfigs,
        }),
        timeout: 30_000,
        maxBuffer: 5_000_000,
        encoding: 'utf8',
        env: {
          ...process.env,
          JS_RUNTIME_VERSION: process.versions.node,
          JS_RUNTIME_NAME: process.release.name,
          NODE_PACKAGE_MANAGER: 'vite-plus',
          VP_RESOLVING_CONFIG_METADATA: '1',
        },
      },
    );
    if (batch.status !== 0) throw new Error(`Generated batch format failed: ${batch.stderr}`);
    const response = batch.stdout
      .split('\n')
      .findLast((line) => line.startsWith('STARTER_FORMAT_BATCH '));
    if (!response) throw new Error('Generated batch format returned no response');
    const output: unknown = JSON.parse(response.slice('STARTER_FORMAT_BATCH '.length));
    if (output !== null) {
      if (
        !Array.isArray(output) ||
        output.length !== scripts.length ||
        output.some((item) => typeof item !== 'string')
      )
        throw new Error('Generated batch format returned invalid output');
      for (const [index, [filename, , key]] of scripts.entries()) {
        const contents = Buffer.from(output[index]);
        files.set(filename, contents);
        formatted.set(key, contents);
      }
    }
  }
  for (const [filename, contents, key] of pending) {
    if (formatted.has(key)) continue;
    const result = spawnSync(process.execPath, [binary, 'fmt', '--stdin-filepath', filename], {
      cwd: root,
      input: contents,
      timeout: 30_000,
      maxBuffer: 5_000_000,
    });
    if (result.status !== 0)
      throw new Error(`Generated format failed for ${filename}: ${result.stderr.toString()}`);
    files.set(filename, result.stdout);
    formatted.set(key, result.stdout);
  }
  return files;
}

export function finalizeManaged(root: string): void {
  const statePath = path.join(root, '.template.json');
  const state = JSON.parse(readFileSync(statePath, 'utf8')) as TemplateState;
  const key = formatterKey(root);
  if (key && state.formatKey === key) return;
  const original = readFileSync(statePath);
  const observed = new Map<string, string>();
  const files: Files = new Map();
  for (const [filename, hash] of Object.entries(state.managed)) {
    const target = safeFile(root, filename);
    if (existsSync(target) && digest(readFileSync(target)) === hash) {
      files.set(filename, readFileSync(target));
      observed.set(filename, hash);
    }
  }
  formatFiles(root, files);
  for (const [filename, contents] of files) {
    state.managed[filename] = digest(contents);
  }
  if (key) state.formatKey = key;
  files.set('.template.json', Buffer.from(`${JSON.stringify(state, null, 2)}\n`));
  observed.set('.template.json', digest(original));
  const entries = [...files.keys()];
  const unchanged = (filename: string): void => {
    if (
      !existsSync(safeFile(root, filename)) ||
      digest(readFileSync(safeFile(root, filename))) !== observed.get(filename)
    )
      throw new Error(
        `User edited during formatting: ${filename}; nothing will be silently overwritten`,
      );
  };
  entries.forEach(unchanged);
  applyFiles(root, files, [], (index) => unchanged(entries[index]!));
}

